import React, { useState, useEffect } from 'react';
import axios from 'axios';

const App = () => {
  const [resorts, setResorts] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    const fetchResorts = async () => {
      try {
        const response = await axios.get('http://localhost:3001/api/ski-resorts');
        setResorts(response.data);
      } catch (error) {
        console.error('Error fetching resorts:', error);
      }
    };

    fetchResorts();
  }, []);

  const handleSearch = () => {
    // Filter resorts based on search input
    return resorts.filter(resort => resort.name.toLowerCase().includes(search.toLowerCase()));
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search resorts"
        value={search}
        onChange={e => setSearch(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>
      <ul>
        {handleSearch().map(resort => (
          <li key={resort.name}>{resort.name}</li>
        ))}
      </ul>
    </div>
  );
};

export default App;
